package com.aetherforge.api;import com.aetherforge.repo.OperationalRepository;import com.aetherforge.repo.QualityRepository;import org.springframework.http.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/v1/reports") public class ReportsController {private final OperationalRepository r;private final QualityRepository q;public ReportsController(OperationalRepository r,QualityRepository q){this.r=r;this.q=q;}@GetMapping("/{type}.csv") public ResponseEntity<String> report(@PathVariable String type){List<Map<String,Object>> rows=switch(type){case "production","factory"->r.production();case "maintenance"->r.maintenance();case "machine-health","ai-insights"->r.predictions();case "energy"->r.energy();case "quality"->q.list();default->List.of();};if(rows.isEmpty())return csv(type,List.of(Map.of("message","No data available")));return csv(type,rows);}private ResponseEntity<String> csv(String type,List<Map<String,Object>> rows){LinkedHashSet<String> headers=new LinkedHashSet<>();rows.forEach(x->headers.addAll(x.keySet()));StringBuilder b=new StringBuilder();b.append(String.join(",",headers)).append('\n');for(var x:rows){List<String> vals=new ArrayList<>();for(String h:headers)vals.add("\""+String.valueOf(x.getOrDefault(h,"")).replace("\"","\"\"")+"\"");b.append(String.join(",",vals)).append('\n');}return ResponseEntity.ok().header(HttpHeaders.CONTENT_DISPOSITION,"attachment; filename="+type+"-report.csv").contentType(MediaType.parseMediaType("text/csv")).body(b.toString());}}
